public class Cookie {
    private String flavor;

    public Cookie(String flavor) {
        this.flavor = flavor;
    }

    public String getFlavor() {
        return flavor;
    }

    public String describe() {
        return flavor + " cookie";
    }
}

public class DecoratedCookie extends Cookie {
    public DecoratedCookie(String flavor) {
        super(flavor);
    }

    @Override
    public String describe() {
        return getFlavor() + " cookie with decorative icing";
    }
}

public class GiftCookie extends DecoratedCookie {
    public GiftCookie(String flavor) {
        super(flavor);
    }

    @Override
    public String describe() {
        return getFlavor() + " cookie in a gift box";
    }

    public String packageCookie(String message) {
        return "Gift box packed: " + getFlavor() + " cookie\nCard reads: " + message;
    }
}
